"""README (корневой, init, main), SCENARIOS.md и scenarios.json (по _registry.jsonl)."""
import json
import os
from collections import OrderedDict
from common import (write, OUT, REGISTRY, SCENARIOS, CTX_M, RECORDS, agent_ctx, HANDLES, ERRORS, INSPECTOR_HANDLES,
                    CHECKLIST, cafe_ctx, cafe_ctx_many, CAFE_NEW_GENERIC, CAFE_NEW_WITH_ADDR, CAFE_SHORT, CAFE_TAGS_SHORT,
                    CAFE_FULL, CAFE_TAGS_FULL, tags_short_str)


def count():
    c = {}
    for d, _, fs in os.walk(OUT):
        if "readme.md" in fs:
            rel = os.path.relpath(d, OUT).split(os.sep)
            if rel[0] == "system":
                key = "system"
            elif rel[1] == "node-isolate":
                key = "/".join(rel[:3])
            else:
                key = "/".join(rel[:2])
            c[key] = c.get(key, 0) + 1
    return c


def counts_table():
    c = count()
    rows = [
        ("init/node-isolate/inspector", "инспектор, node-isolate"),
        ("init/node-isolate/curator", "куратор, node-isolate"),
        ("init/e2e", "init, e2e"),
        ("main/node-isolate/orchestrator", "оркестратор, node-isolate"),
        ("main/node-isolate/local", "локальный агент, node-isolate"),
        ("main/e2e", "main, e2e"),
    ]
    total = sum(v for k, v in c.items() if k != "system")
    lines = ["| Часть | Тестов | Доля eval-сета |", "|---|---|---|"]
    for key, name in rows:
        n = c.get(key, 0)
        lines.append("| %s (`%s`) | %d | %d %% |" % (name, key, n, round(100 * n / total)))
    ni = sum(v for k, v in c.items() if "node-isolate" in k)
    e2e = total - ni
    lines.append("| **eval-сет, всего** | **%d** | node-isolate %d %%, e2e %d %% |" % (total, round(100 * ni / total), round(100 * e2e / total)))
    lines.append("| системные тесты (`system/`), вне eval-сета | %d | — |" % c.get("system", 0))
    return "\n".join(lines), total


